package se.mickelus.tetra.blocks.scroll;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.material.PushReaction;
import net.minecraft.world.level.storage.loot.LootParams;
import net.minecraft.world.level.storage.loot.parameters.LootContextParams;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.Vec3;
import se.mickelus.mutil.util.TileEntityOptional;
import se.mickelus.tetra.blocks.ICraftingEffectProviderBlock;
import se.mickelus.tetra.blocks.ISchematicProviderBlock;
import se.mickelus.tetra.blocks.TetraBlock;
import se.mickelus.tetra.blocks.workbench.AbstractWorkbenchBlock;

import javax.annotation.Nullable;
import javax.annotation.ParametersAreNonnullByDefault;
import java.util.Arrays;
import java.util.List;

@ParametersAreNonnullByDefault
public class ScrollBlock extends TetraBlock implements EntityBlock, ISchematicProviderBlock, ICraftingEffectProviderBlock {
    public static final ResourceLocation scrollDynamicDropId = new ResourceLocation("tetra:scroll");
    public static final SoundType sound = new SoundType(0.8F, 1.3F, SoundEvents.BOOK_PAGE_TURN, SoundEvents.BOOK_PAGE_TURN,
            SoundEvents.BOOK_PAGE_TURN, SoundEvents.BOOK_PAGE_TURN, SoundEvents.BOOK_PAGE_TURN);
    private final Arrangement arrangement;

    public ScrollBlock(Arrangement arrangement) {
        super(Properties.of().sound(sound).instabreak().pushReaction(PushReaction.DESTROY));

        this.arrangement = arrangement;
        this.registerDefaultState(this.defaultBlockState().setValue(BlockStateProperties.HORIZONTAL_FACING, Direction.EAST));
    }

    public Arrangement getArrangement() {
        return arrangement;
    }

    @Override
    public boolean canUnlockSchematics(Level world, BlockPos pos, BlockPos targetPos) {
        boolean isIntricate = TileEntityOptional.from(world, pos, ScrollTile.class).map(ScrollTile::isIntricate).orElse(false);
        return !isIntricate || targetPos.above().equals(pos);
    }

    @Override
    public ResourceLocation[] getSchematics(Level world, BlockPos pos, BlockState blockState) {
        return TileEntityOptional.from(world, pos, ScrollTile.class).map(ScrollTile::getSchematics).orElseGet(() -> new ResourceLocation[0]);
    }

    @Override
    public boolean canUnlockCraftingEffects(Level world, BlockPos pos, BlockPos targetPos) {
        boolean isIntricate = TileEntityOptional.from(world, pos, ScrollTile.class).map(ScrollTile::isIntricate).orElse(false);
        return !isIntricate || targetPos.above().equals(pos);
    }

    @Override
    public ResourceLocation[] getCraftingEffects(Level world, BlockPos pos, BlockState blockState) {
        return TileEntityOptional.from(world, pos, ScrollTile.class).map(ScrollTile::getCraftingEffects).orElseGet(() -> new ResourceLocation[0]);
    }

    @Override
    public InteractionResult use(BlockState state, Level world, BlockPos pos, Player player, InteractionHand hand, BlockHitResult hit) {
        if (arrangement == Arrangement.open) {
            BlockState offsetState = world.getBlockState(pos.below());

            if (offsetState.getBlock() instanceof AbstractWorkbenchBlock) {
                return offsetState.use(world, player, hand, new BlockHitResult(Vec3.ZERO, Direction.UP, pos.below(), true));
            }
        }

        return super.use(state, world, pos, player, hand, hit);
    }

    @Override
    public boolean canSurvive(BlockState state, LevelReader world, BlockPos pos) {
        Direction facing = Direction.UP;
        if (getArrangement() == Arrangement.wall) {
            facing = state.getValue(BlockStateProperties.HORIZONTAL_FACING);
        }

        BlockPos offsetPos = pos.relative(facing.getOpposite());
        BlockState offsetState = world.getBlockState(offsetPos);

        if (getArrangement() == Arrangement.open) {
            return offsetState.getBlock() instanceof AbstractWorkbenchBlock;
        }

        return offsetState.isFaceSturdy(world, offsetPos, facing);
    }

    @Override
    public BlockState updateShape(BlockState blockState, Direction facing, BlockState facingState, LevelAccessor world, BlockPos currentPos,
            BlockPos facingPos) {
        if (!blockState.canSurvive(world, currentPos)) {
            return Blocks.AIR.defaultBlockState();
        }

        return blockState;
    }

    @Override
    protected void createBlockStateDefinition(StateDefinition.Builder<Block, BlockState> builder) {
        super.createBlockStateDefinition(builder);
        builder.add(BlockStateProperties.HORIZONTAL_FACING);
    }

    @Override
    public RenderShape getRenderShape(BlockState state) {
        return RenderShape.ENTITYBLOCK_ANIMATED;
    }

    public List<ItemStack> getDrops(BlockState blockState, LootParams.Builder lootParams) {
        BlockEntity blockentity = lootParams.getOptionalParameter(LootContextParams.BLOCK_ENTITY);
        if (blockentity instanceof ScrollTile tile) {
            lootParams.withDynamicDrop(scrollDynamicDropId, (consumer) ->
                    Arrays.stream(tile.getItemTags())
                            .map(nbt -> {
                                ItemStack itemStack = new ItemStack(ScrollItem.instance);
                                itemStack.addTagElement("BlockEntityTag", nbt);
                                return itemStack;
                            })
                            .forEach(consumer)
            );

        }

        return super.getDrops(blockState, lootParams);
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos blockPos, BlockState blockState) {
        return new ScrollTile(blockPos, blockState);
    }

    public enum Arrangement {
        wall,
        open,
        rolled
    }
}

package se.mickelus.tetra.blocks.scroll;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.mojang.datafixers.util.Pair;
import com.mojang.serialization.Codec;
import com.mojang.serialization.DataResult;
import com.mojang.serialization.JsonOps;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.nbt.ListTag;
import net.minecraft.nbt.NbtOps;
import net.minecraft.nbt.Tag;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.ItemStack;
import se.mickelus.mutil.util.HexCodec;

import javax.annotation.ParametersAreNonnullByDefault;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Optional;
import java.util.stream.Collectors;

@ParametersAreNonnullByDefault
public class ScrollData {
    private static final Codec<ScrollData> codec = RecordCodecBuilder.create(instance -> instance.group(
            Codec.STRING.fieldOf("key").forGetter(i -> i.key),
            Codec.STRING.optionalFieldOf("details").forGetter(i -> Optional.ofNullable(i.details)),
            Codec.BOOL.fieldOf("intricate").forGetter(i -> i.isIntricate),
            Codec.INT.fieldOf("material").forGetter(i -> i.material),
            HexCodec.instance.fieldOf("ribbon").forGetter(i -> i.ribbon),
            Codec.INT.listOf().optionalFieldOf("glyphs", Collections.emptyList()).forGetter(i -> i.glyphs),
            ResourceLocation.CODEC.listOf().optionalFieldOf("schematics", Collections.emptyList()).forGetter(i -> i.schematics),
            ResourceLocation.CODEC.listOf().optionalFieldOf("effects", Collections.emptyList()).forGetter(i -> i.craftingEffects)
    ).apply(instance, ScrollData::new));
    public String key;
    public String details;
    public boolean isIntricate;
    public int material = 0;
    public int ribbon = 0xffffff;
    public List<Integer> glyphs = Collections.emptyList();
    public List<ResourceLocation> schematics = Collections.emptyList();
    public List<ResourceLocation> craftingEffects = Collections.emptyList();

    public ScrollData() {
        key = "unknown";
    }

    public ScrollData(String name, Optional<String> details, boolean isIntricate, int material, int ribbon, List<Integer> glyphs, List<ResourceLocation> schematics, List<ResourceLocation> craftingEffects) {
        this.key = name;
        this.details = details.orElse(null);
        this.isIntricate = isIntricate;

        this.material = material;
        this.ribbon = ribbon;
        this.glyphs = glyphs;

        if (!schematics.isEmpty()) {
            this.schematics = schematics;
        }

        if (!craftingEffects.isEmpty()) {
            this.craftingEffects = craftingEffects;
        }
    }

    public static int readMaterialFast(ItemStack itemStack) {
        return Optional.ofNullable(itemStack.getTagElement("BlockEntityTag"))
                .map(tag -> tag.getList("data", Tag.TAG_COMPOUND))
                .filter(list -> list.size() > 0)
                .map(list -> list.getCompound(0))
                .map(tag -> tag.getInt("material"))
                .orElse(0);
    }

    public static int readRibbonFast(ItemStack itemStack) {
        return Optional.ofNullable(itemStack.getTagElement("BlockEntityTag"))
                .map(tag -> tag.getList("data", Tag.TAG_COMPOUND))
                .filter(list -> list.size() > 0)
                .map(list -> list.getCompound(0))
                .map(tag -> tag.getString("ribbon"))
                .map(hex -> (int) Long.parseLong(hex, 16))
                .orElse(0);
    }

    public static ScrollData read(ItemStack itemStack) {
        return Optional.ofNullable(itemStack.getTagElement("BlockEntityTag"))
                .map(ScrollData::read)
                .filter(data -> data.length > 0)
                .map(data -> data[0])
                .orElseGet(ScrollData::new);
    }

    public static ScrollData[] read(CompoundTag tag) {
        return tag.getList("data", Tag.TAG_COMPOUND).stream()
                .map(nbt -> ScrollData.codec.decode(NbtOps.INSTANCE, nbt))
                .map(DataResult::result)
                .filter(Optional::isPresent)
                .map(Optional::get)
                .map(Pair::getFirst)
                .toArray(ScrollData[]::new);
    }

    public static CompoundTag write(ScrollData[] data, CompoundTag tag) {
        ListTag list = Arrays.stream(data)
                .map(scroll -> ScrollData.codec.encodeStart(NbtOps.INSTANCE, scroll))
                .map(DataResult::result)
                .filter(Optional::isPresent)
                .map(Optional::get)
                .collect(Collectors.toCollection(ListTag::new));
        tag.put("data", list);
        return tag;
    }

    public static ScrollData read(JsonObject json) {
        return Optional.of(ScrollData.codec.decode(JsonOps.INSTANCE, json))
                .flatMap(DataResult::result)
                .map(Pair::getFirst)
                .orElse(null);
    }

    public void write(ItemStack itemStack) {
        itemStack.addTagElement("BlockEntityTag", ScrollData.write(new ScrollData[]{this}, new CompoundTag()));
    }

    public JsonElement write(JsonObject json) {
        return Optional.of(ScrollData.codec.encode(this, JsonOps.INSTANCE, json))
                .flatMap(DataResult::result)
                .orElse(null);
    }
}

package se.mickelus.tetra.blocks.scroll;

import com.google.common.collect.ImmutableList;
import com.google.common.collect.Lists;
import net.minecraft.ChatFormatting;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.renderer.item.ItemProperties;
import net.minecraft.client.resources.language.I18n;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.InteractionResultHolder;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.TooltipFlag;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.api.distmarker.OnlyIn;
import net.minecraftforge.common.MinecraftForge;
import net.minecraftforge.forgespi.Environment;
import net.minecraftforge.registries.ObjectHolder;
import se.mickelus.mutil.network.PacketHandler;
import se.mickelus.mutil.util.TileEntityOptional;
import se.mickelus.tetra.TetraMod;
import se.mickelus.tetra.Tooltips;
import se.mickelus.tetra.blocks.scroll.gui.ScrollScreen;
import se.mickelus.tetra.blocks.workbench.AbstractWorkbenchBlock;
import se.mickelus.tetra.items.InitializableItem;

import javax.annotation.Nullable;
import javax.annotation.ParametersAreNonnullByDefault;
import java.util.*;
import java.util.stream.Collectors;

@ParametersAreNonnullByDefault
public class ScrollItem extends BlockItem implements InitializableItem {
    public static final String identifier = "scroll_rolled";
    @ObjectHolder(registryName = "item", value = TetraMod.MOD_ID + ":" + identifier)
    public static ScrollItem instance;


    public static ItemStack gemExpertise;
    public static ItemStack metalExpertise;
    public static ItemStack woodExpertise;
    public static ItemStack stoneExpertise;
    public static ItemStack fibreExpertise;
    public static ItemStack skinExpertise;
    public static ItemStack boneExpertise;
    public static ItemStack fabricExpertise;
    public static ItemStack scaleExpertise;
    public static ItemStack hammerEfficiency;
    public static ItemStack axeEfficiency;
    public static ItemStack cutEfficiency;
    public static ItemStack sturdyGuard;
    public static ItemStack throwingKnife;
    public static ItemStack howlingBlade;

    public ScrollItem(Block block) {
        super(block, new Properties().stacksTo(1));

        MinecraftForge.EVENT_BUS.register(new ScrollDrops());
    }

    @Override
    public void commonInit(PacketHandler packetHandler) {
        gemExpertise = setupTreatise("gem_expertise", false, 0, 0x2bffee, 14, 13, 14, 15);
        metalExpertise = setupTreatise("metal_expertise", false, 0, 0xffffff, 4, 6, 6, 5);
        woodExpertise = setupTreatise("wood_expertise", false, 0, 0xbf934b, 2, 1, 2, 1);
        stoneExpertise = setupTreatise("stone_expertise", false, 0, 0x9a9a9a, 2);
        fibreExpertise = setupTreatise("fibre_expertise", false, 0, 0xa88054, 5, 10, 11, 4);
        skinExpertise = setupTreatise("skin_expertise", false, 0, 0xbf6930, 0, 1, 1, 1);
        boneExpertise = setupTreatise("bone_expertise", false, 0, 0xfff193, 12, 14, 12, 14);
        fabricExpertise = setupTreatise("fabric_expertise", false, 0, 0xff3333, 5, 3, 6, 4);
        scaleExpertise = setupTreatise("scale_expertise", false, 0, 0x75a03e, 6, 7, 6, 8);
        hammerEfficiency = setupTreatise("hammer_efficiency", false, 0, 0xff6666, 6, 7, 6, 11);
        axeEfficiency = setupTreatise("axe_efficiency", false, 0, 0x66ff66, 0, 1, 3, 3);
        cutEfficiency = setupTreatise("cut_efficiency", false, 0, 0x6666ff, 4, 0, 3, 5);

        sturdyGuard = setupSchematic("sword/sturdy_guard", null, false, 1, 0xbcb8b5, 3, 2, 2, 1);
        throwingKnife = setupSchematic("sword/throwing_knife", null, false, 1, 0xb8ced9, 4, 1, 0, 5);
        howlingBlade = setupSchematic("sword/howling", null, false, 1, 0xfaf396, 8, 9, 10, 5);
    }

    @OnlyIn(Dist.CLIENT)
    @Override
    public void clientInit() {
        Minecraft.getInstance().getItemColors().register(new ScrollItemColor(), instance);
        ItemProperties.register(instance, new ResourceLocation(TetraMod.MOD_ID, "scroll_mat"),
                (itemStack, world, livingEntity, i) -> ScrollData.readMaterialFast(itemStack));
    }

    public Collection<ItemStack> getCreativeTabItems() {
        return Lists.newArrayList(
                sturdyGuard,
                throwingKnife,
                howlingBlade,
                gemExpertise,
                metalExpertise,
                woodExpertise,
                stoneExpertise,
                fibreExpertise,
                skinExpertise,
                boneExpertise,
                fabricExpertise,
                scaleExpertise,
                hammerEfficiency,
                axeEfficiency,
                cutEfficiency,
                setupSchematic("hone/gild_1", null, true, 2, 0xc9ae69, 15, 14, 15, 15),
                setupSchematic("hone/gild_5", null,
                        new String[] { "hone/gild_1", "hone/gild_2", "hone/gild_3", "hone/gild_4", "hone/gild_5" },
                        true, 2, 0xf2b313, 12, 12, 12, 12),
                setupSchematic("warforge/adze", "warforge", false, 2, 0x8559b3, 6, 7, 11, 7),
                setupSchematic("warforge/axe", "warforge", false, 2, 0xb35973, 5, 10, 8, 9),
                setupSchematic("warforge/hammer", "warforge", false, 2, 0x3d4299, 9, 8, 11, 10),
                setupSchematic("warforge/pickaxe", "warforge", false, 2, 0x508cb3, 6, 11, 8, 7),
                setupSchematic("warforge/claw", "warforge", false, 2, 0x1d262f, 8, 10, 5, 11),
                setupSchematic("warforge/hoe", "warforge", false, 2, 0x93b350, 10, 7, 9, 5),
                setupSchematic("warforge/sickle", "warforge", false, 2, 0xd99e4c, 5, 9, 6, 10),
                setupSchematic("warforge/butt", "warforge", false, 2, 0xb33636, 11, 5, 8, 9)
        );
    }

    private ItemStack setupSchematic(String key, String details, boolean isIntricate, int material, int tint, Integer... glyphs) {
        return setupSchematic(key, details, new String[] { key }, isIntricate, material, tint, glyphs);
    }

    private ItemStack setupSchematic(String key, String details, String[] schematics, boolean isIntricate, int material, int tint, Integer... glyphs) {
        ScrollData data = new ScrollData(key, Optional.ofNullable(details), isIntricate, material, tint, Arrays.asList(glyphs),
                Arrays.stream(schematics).map(s -> new ResourceLocation(TetraMod.MOD_ID, s))
                        .collect(Collectors.toList()),
                Collections.emptyList());

        ItemStack itemStack = new ItemStack(this);
        data.write(itemStack);

        return itemStack;
    }

    private ItemStack setupTreatise(String key, boolean isIntricate, int material, int tint, Integer... glyphs) {
        ScrollData data = new ScrollData(key, Optional.empty(), isIntricate, material, tint, Arrays.asList(glyphs), Collections.emptyList(),
                ImmutableList.of(new ResourceLocation(TetraMod.MOD_ID, key)));

        ItemStack itemStack = new ItemStack(this);
        data.write(itemStack);

        return itemStack;
    }

    @Override
    public Component getName(ItemStack stack) {
        String key = ScrollData.read(stack).key;
        // sometimes called on the server, need to check before calling I18n
        if (!Environment.get().getDist().isDedicatedServer()) {
            String prefixKey = "item.tetra.scroll." + key + ".prefix";
            if (I18n.exists(prefixKey)) {
                return Component.translatable("item.tetra.scroll." + key + ".prefix")
                        .append(Component.literal(": "))
                        .append(Component.translatable("item.tetra.scroll." + key + ".name"));
            }
        }

        return Component.translatable("item.tetra.scroll." + key + ".name");
    }

    @Override
    public void appendHoverText(ItemStack itemStack, @Nullable Level worldIn, List<Component> tooltip, TooltipFlag flagIn) {
        ScrollData data = ScrollData.read(itemStack);
        StringJoiner attributes = new StringJoiner(" ");

        if (!ScrollData.read(itemStack).schematics.isEmpty()) {
            attributes.add(ChatFormatting.DARK_PURPLE + I18n.get("item.tetra.scroll.schematics"));
        }

        if (!ScrollData.read(itemStack).craftingEffects.isEmpty()) {
            attributes.add(ChatFormatting.DARK_AQUA + I18n.get("item.tetra.scroll.effects"));
        }

        if (data.isIntricate) {
            attributes.add(ChatFormatting.GOLD + I18n.get("item.tetra.scroll.intricate"));
        }

        tooltip.add(Component.literal(attributes.toString()));
        tooltip.add(Component.literal(" "));
        tooltip.add(Component.translatable("item.tetra.scroll." + data.key + ".description").withStyle(ChatFormatting.GRAY));
        tooltip.add(Component.literal(" "));

        if (Screen.hasShiftDown()) {
            tooltip.add(Tooltips.expanded);

            if (!ScrollData.read(itemStack).schematics.isEmpty()) {
                tooltip.add(Component.literal(" "));
                tooltip.add(Component.translatable("item.tetra.scroll.schematics").withStyle(ChatFormatting.UNDERLINE, ChatFormatting.DARK_PURPLE));
                tooltip.add(Component.translatable("item.tetra.scroll.schematics.description").withStyle(ChatFormatting.GRAY));
            }

            if (!ScrollData.read(itemStack).craftingEffects.isEmpty()) {
                tooltip.add(Component.literal(" "));
                tooltip.add(Component.translatable("item.tetra.scroll.effects").withStyle(ChatFormatting.UNDERLINE, ChatFormatting.DARK_AQUA));
                tooltip.add(Component.translatable("item.tetra.scroll.effects.description").withStyle(ChatFormatting.GRAY));
            }

            if (data.isIntricate) {
                tooltip.add(Component.literal(" "));
                tooltip.add(Component.translatable("item.tetra.scroll.intricate").withStyle(ChatFormatting.UNDERLINE, ChatFormatting.GOLD));
                tooltip.add(Component.translatable("item.tetra.scroll.intricate.description").withStyle(ChatFormatting.GRAY));
            } else {
                tooltip.add(Component.literal(" "));
                tooltip.add(Component.translatable("item.tetra.scroll.range.description").withStyle(ChatFormatting.GRAY));
            }

            if (I18n.exists("item.tetra.scroll." + data.key + ".description_extended")) {
                tooltip.add(Component.literal(" "));
                tooltip.add(Component.translatable("item.tetra.scroll." + data.key + ".description_extended").withStyle(ChatFormatting.GRAY));
            }
        } else {
            tooltip.add(Tooltips.expand);
        }

        if (flagIn.isAdvanced()) {
            tooltip.add(Component.literal("s: " + data.schematics + ",e: " + data.craftingEffects));
        }
    }

    private boolean openScroll(ItemStack itemStack, boolean isRemote) {
        ScrollData data = ScrollData.read(itemStack);
        if (data.details != null) {
            if (isRemote) {
                showDetailsScreen(data.details);
            }
            return true;
        }

        return false;
    }

    @OnlyIn(Dist.CLIENT)
    private void showDetailsScreen(String detailsKey) {
        ScrollScreen screen = new ScrollScreen(detailsKey);
        Minecraft.getInstance().setScreen(screen);
    }

    @Override
    public InteractionResultHolder<ItemStack> use(Level world, Player player, InteractionHand hand) {
        ItemStack itemstack = player.getItemInHand(hand);
        if (openScroll(player.getItemInHand(hand), world.isClientSide)) {
            return InteractionResultHolder.sidedSuccess(itemstack, world.isClientSide());
        }
        return InteractionResultHolder.pass(itemstack);
    }

    @Override
    public InteractionResult useOn(UseOnContext context) {
        Level world = context.getLevel();
        BlockPos pos = context.getClickedPos();
        ItemStack itemStack = context.getItemInHand();
        Player player = context.getPlayer();
        Block block = context.getLevel().getBlockState(context.getClickedPos()).getBlock();

        if (!(block instanceof AbstractWorkbenchBlock) && player != null && player.isCrouching() && openScroll(itemStack, world.isClientSide)) {
            return InteractionResult.sidedSuccess(world.isClientSide);
        }

        // add scroll to an existing stack of rolled up scrolls
        if (RolledScrollBlock.instance.equals(block)) {
            boolean success = TileEntityOptional.from(world, pos, ScrollTile.class)
                    .map(tile -> tile.addScroll(itemStack))
                    .orElse(false);

            if (success) {
                if (player == null || !player.getAbilities().instabuild) {
                    itemStack.shrink(1);
                }
                return InteractionResult.sidedSuccess(world.isClientSide);
            }
        }

        return place(new BlockPlaceContext(context));
    }

    @Nullable
    @Override
    protected BlockState getPlacementState(BlockPlaceContext context) {
        BlockState state = getBlock().defaultBlockState();

        if (context.getClickedFace().getAxis().getPlane() == Direction.Plane.HORIZONTAL) {
            state = WallScrollBlock.instance.defaultBlockState()
                    .setValue(BlockStateProperties.HORIZONTAL_FACING, context.getClickedFace());
        } else {
            if (context.getLevel().getBlockState(context.getClickedPos().relative(context.getClickedFace().getOpposite())).getBlock() instanceof AbstractWorkbenchBlock) {
                state = OpenScrollBlock.instance.defaultBlockState();
            }

            state = state.setValue(BlockStateProperties.HORIZONTAL_FACING, context.getHorizontalDirection());
        }

        return canPlace(context, state) ? state : null;
    }
}

package se.mickelus.tetra.blocks.scroll;

import net.minecraft.core.BlockPos;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraftforge.registries.ObjectHolder;
import org.apache.commons.lang3.ArrayUtils;
import se.mickelus.tetra.TetraMod;

import javax.annotation.Nullable;
import javax.annotation.ParametersAreNonnullByDefault;
import java.util.Arrays;
import java.util.Collection;

@ParametersAreNonnullByDefault
public class ScrollTile extends BlockEntity {
    public static final String identifier = "scroll";
    @ObjectHolder(registryName = "block_entity_type", value = TetraMod.MOD_ID + ":" + identifier)
    public static BlockEntityType<ScrollTile> type;

    private ScrollData[] scrolls = new ScrollData[0];

    public ScrollTile(BlockPos p_155268_, BlockState p_155269_) {
        super(type, p_155268_, p_155269_);
    }

    public ScrollData[] getScrolls() {
        return scrolls;
    }

    public boolean addScroll(ItemStack itemStack) {
        if (scrolls.length < 6) {
            scrolls = ArrayUtils.add(scrolls, ScrollData.read(itemStack));
            setChanged();
            return true;
        }
        return false;
    }

    public ResourceLocation[] getSchematics() {
        boolean isIntricate = isIntricate();
        return Arrays.stream(scrolls)
                .filter(data -> data.isIntricate == isIntricate)
                .map(data -> data.schematics)
                .flatMap(Collection::stream)
                .toArray(ResourceLocation[]::new);
    }

    public ResourceLocation[] getCraftingEffects() {
        boolean isIntricate = isIntricate();
        return Arrays.stream(scrolls)
                .filter(data -> data.isIntricate == isIntricate)
                .map(data -> data.craftingEffects)
                .flatMap(Collection::stream)
                .toArray(ResourceLocation[]::new);
    }

    public boolean isIntricate() {
        return !Arrays.stream(scrolls)
                .anyMatch(data -> !data.isIntricate);
    }

    public CompoundTag[] getItemTags() {
        return Arrays.stream(scrolls)
                .map(data -> new ScrollData[]{data})
                .map(data -> ScrollData.write(data, new CompoundTag()))
                .toArray(CompoundTag[]::new);
    }

    @Override
    public AABB getRenderBoundingBox() {
        return Shapes.block().bounds().move(worldPosition);
    }

    @Nullable
    @Override
    public ClientboundBlockEntityDataPacket getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    @Override
    public CompoundTag getUpdateTag() {
        return saveWithoutMetadata();
    }

    @Override
    public void load(CompoundTag compound) {
        super.load(compound);

        scrolls = ScrollData.read(compound);
    }

    @Override
    public void saveAdditional(CompoundTag compound) {
        super.saveAdditional(compound);

        ScrollData.write(scrolls, compound);
    }
}

package se.mickelus.tetra.blocks.workbench;

import com.mojang.datafixers.util.Pair;
